const D = { energy: .55, scale: 1, bloom: .5, grain: .35, density: .5, alpha: .85, hue: 18, speed: 1, x: .5, y: .5, style: 'halation', act: 'expose', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// RESCUE NOTE: v1 was STATIC (motion .0034, gate is .004) over the validator's
// dark navy bed. A bloom pass has nothing to bloom against on a dark frame —
// the highlight-detect found no pixel over its .34 threshold, so steps 1-2 were
// no-ops, and the only intrinsic mover (the gate flare) ran at alpha ~.04, which
// is invisible. A post pass has to CARRY ITS OWN LIGHT: the light-leak, the gate
// flare and the veil below are all intrinsic, present on any frame, and they
// wander on incommensurate K.t rates so the pass never re-phases. Amplitude is
// tuned to sit ~10x over the motion floor and ~10x under the .35 strobe ceiling.

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=(((h%360)+360)%360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [((r+m)*255)|0,((g+m)*255)|0,((l+m)*255)|0]; };
const rgba=(c,a)=>'rgba('+c[0]+','+c[1]+','+c[2]+','+a.toFixed(4)+')';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const bl=cl(P.bloom,0,1.4), gr=cl(P.grain,0,1), al=cl(P.alpha,0,1);
const sc=cl(P.scale,.5,2.2), dens=cl(P.density,0,1), spd=cl(P.speed,.2,4);
const en=cl(P.energy,0,1)*(.55+.55*K.intensity);
const T=K.t*spd, H=md(P.hue,360);
const ax=cl(P.x,0,1), ay=cl(P.y,0,1);

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;
const kick=Math.min(1,K.pulse*.4+S.bass*.55);

// ---- film stock: what the emulsion does to the light ----
const bleach=(sty==='bleach'), xpro=(sty==='cross_process'), ir=(sty==='infrared');
let hH,hS,hB, veilH,veilS, grainMul=1, bloomMul=1;
if(bleach){ hH=md(H+188,360); hS=10; hB=100; veilH=md(H+196,360); veilS=22; grainMul=1.45; bloomMul=.7; }
else if(xpro){ hH=md(H+168,360); hS=52; hB=100; veilH=md(H+176,360); veilS=44; grainMul=1.0; bloomMul=1.1; }
else if(ir){ hH=md(H+300,360); hS=34; hB=100; veilH=md(H+308,360); veilS=40; grainMul=.8; bloomMul=1.5; }
else { hH=md(H,360); hS=58; hB=100; veilH=md(H+6,360); veilS=48; grainMul=1; bloomMul=1; }

let bloomE=bl*bloomMul, grainE=gr*grainMul, veilE=1;
if(act==='flare'){ bloomE*=.8+1.5*K.intensity*(.5+.5*K.swell)+.5*kick*en; }
else if(act==='decay'){ const q=.5+.5*Math.sin(T*.021); grainE*=.7+.9*q; veilE=.6+1.5*q; }

const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// ---- the halation sprite: one pre-blurred glow, reused (never tint() in the loop) ----
const skey=Math.round(hH)+'|'+Math.round(hS);
if(!S.spr||S.sk!==skey){
  const g=(S.spr&&S.spr.width===160)?S.spr:createGraphics(160,160);
  g.colorMode(HSB,360,100,100,100); g.clear();
  const gd=g.drawingContext.createRadialGradient(80,80,0,80,80,80);
  const c0=hsb2rgb(hH,hS*.35,hB), c1=hsb2rgb(hH,hS,hB*.92), c2=hsb2rgb(md(hH-14,360),Math.min(100,hS+24),hB*.7);
  gd.addColorStop(0,'rgba('+c0[0]+','+c0[1]+','+c0[2]+',1)');
  gd.addColorStop(.18,'rgba('+c1[0]+','+c1[1]+','+c1[2]+',0.62)');
  gd.addColorStop(.45,'rgba('+c2[0]+','+c2[1]+','+c2[2]+',0.20)');
  gd.addColorStop(.75,'rgba('+c2[0]+','+c2[1]+','+c2[2]+',0.05)');
  gd.addColorStop(1,'rgba('+c2[0]+','+c2[1]+','+c2[2]+',0)');
  g.drawingContext.fillStyle=gd; g.drawingContext.fillRect(0,0,160,160);
  S.spr=g; S.sk=skey; }
const spr=S.spr;

// ---- 1. stock colour: separable blend ops re-grade the whole frame ----
if(bleach){
  dc.globalCompositeOperation='saturation'; dc.globalAlpha=cl(.32+.34*(1-en),0,.85)*al;
  dc.fillStyle='rgb(128,128,128)'; dc.fillRect(0,0,W,Hh);
  dc.globalAlpha=1; dc.globalCompositeOperation=oldOp;
} else if(xpro){
  const dh=md(H+150+58*Math.sin(T*.037)+22*Math.sin(T*.0913),360), c=hsb2rgb(dh,58,60);
  dc.globalCompositeOperation='color'; dc.globalAlpha=cl(.16+.20*en,0,.5)*al;
  dc.fillStyle='rgb('+c[0]+','+c[1]+','+c[2]+')'; dc.fillRect(0,0,W,Hh);
  dc.globalAlpha=1; dc.globalCompositeOperation=oldOp;
} else if(ir){
  const dh=md(H+280+40*Math.sin(T*.029),360), c=hsb2rgb(dh,72,70);
  dc.globalCompositeOperation='hue'; dc.globalAlpha=cl(.30+.28*en,0,.7)*al;
  dc.fillStyle='rgb('+c[0]+','+c[1]+','+c[2]+')'; dc.fillRect(0,0,W,Hh);
  dc.globalAlpha=1; dc.globalCompositeOperation=oldOp;
}

// ---- 2. halation: light scattering back off the film base around the highlights ----
// Still a genuine post pass: when there IS content under us, its highlights bloom.
// When there is not, steps 3-5 carry the frame on their own.
const SW=64, SH=cl(Math.round(64*Hh/Math.max(1,W)),18,64);
if(!S.samp||S.sw!==SW||S.sh!==SH){ if(S.samp&&S.samp.remove)S.samp.remove(); S.samp=createGraphics(SW,SH); S.sw=SW; S.sh=SH; }
const samp=S.samp; samp.clear(); samp.drawingContext.imageSmoothingEnabled=true;
try{ samp.drawingContext.drawImage(dc.canvas,0,0,SW,SH); }catch(e){}
samp.loadPixels();
const sp2=samp.pixels;
dc.globalCompositeOperation='lighter';
if(sp2 && sp2.length>=SW*SH*4 && bloomE>0.01){
  let mx=0;
  for(let i=0;i<SW*SH;i++){ const o=i*4; const L=(sp2[o]*.30+sp2[o+1]*.59+sp2[o+2]*.11)/255; if(L>mx)mx=L; }
  const thr=Math.max(.22, mx*.62);
  let n=0;
  const cw=W/SW, ch=Hh/SH;
  for(let j=0;j<SH && n<44;j++) for(let i=0;i<SW && n<44;i++){
    const o=(j*SW+i)*4, L=(sp2[o]*.30+sp2[o+1]*.59+sp2[o+2]*.11)/255;
    if(L<thr) continue;
    n++;
    const rr=u*(.045+.10*bloomE)*sc*(.55+.9*(L-thr)/Math.max(.05,1-thr));
    dc.globalAlpha=cl((.055+.14*bloomE)*(.5+.7*en)*al,0,.6);
    image(spr,(i+.5)*cw-rr,(j+.5)*ch-rr,rr*2,rr*2);
  }
  dc.globalAlpha=1;
}

// ---- 3. gate flare: INTRINSIC scattered light, present on ANY frame ----
// This is the motion floor. Each source wanders on its own pair of
// incommensurate rates, so the pass is never the same 8s later.
const NFL=2+Math.round(dens*2);
for(let i=0;i<NFL;i++){
  const w1=.031+fr(i*7)*.045, w2=.017+fr(i*7+1)*.033, ph=fr(i*7+2)*TAU;
  // three independent rates per axis: with only two, all the sources can stall
  // at their turning points together and the 8s diff collapses into a trough.
  const fx=(ax-.5)+.44*Math.sin(T*w1*7.3+ph)+.20*Math.sin(T*w2*11.1+ph*1.7)+.13*Math.sin(T*w1*3.7+ph*2.9);
  const fy=(ay-.5)+.34*Math.cos(T*w1*5.9+ph*.7)+.16*Math.sin(T*w2*9.3+ph)+.11*Math.cos(T*w2*4.3+ph*1.3);
  const pk=.6+.4*Math.sin(T*.083+i*2.2)+.2*Math.sin(T*.191+i);
  const rr=u*(.20+.16*fr(i*11))*sc*(.6+.55*bloomE)*(.8+.3*pk);
  dc.globalAlpha=cl((.14+.19*bloomE)*(.5+.7*en)*(.6+.5*pk)*al,0,.42);
  image(spr,(fx+.5)*W-rr,(fy+.5)*Hh-rr,rr*2,rr*2);
}
dc.globalAlpha=1;

// ---- 4. light leak: a soft bar of scattered light walking the gate ----
{
  const la=.5+.22*Math.sin(T*.013), ux=Math.cos(la), uy=Math.sin(la);
  const L2=Math.abs(W*ux)+Math.abs(Hh*uy)+1;
  const cpos=(.5+.5*Math.sin(T*.0431+.8*Math.sin(T*.0173)))*L2;
  const bw=u*(.17+.13*bloomE)*sc;
  const ox=W/2-(L2/2-cpos)*ux, oy=Hh/2-(L2/2-cpos)*uy;
  const lc=hsb2rgb(md(hH+8,360),Math.min(100,hS+10),100);
  const lg=dc.createLinearGradient(ox-bw*ux,oy-bw*uy,ox+bw*ux,oy+bw*uy);
  const la2=cl((.030+.055*bloomE)*(.45+.75*en)*al,0,.14);
  lg.addColorStop(0,rgba(lc,0));
  lg.addColorStop(.5,rgba(lc,la2));
  lg.addColorStop(1,rgba(lc,0));
  dc.fillStyle=lg; dc.fillRect(0,0,W,Hh);
}

// ---- 5. warm veil: soft drifting fog over the whole plate ----
const vx=(.5+.30*Math.sin(T*.043)+.12*Math.sin(T*.101))*W, vy=(.5+.24*Math.cos(T*.037)+.10*Math.sin(T*.089))*Hh;
const vc=hsb2rgb(veilH,veilS,96);
const vg=dc.createRadialGradient(vx,vy,u*.05,vx,vy,u*(.9+.12*Math.sin(T*.027)));
vg.addColorStop(0,rgba(vc,cl(.085*veilE*(.4+.8*en)*al,0,.18)));
vg.addColorStop(.55,rgba(vc,cl(.034*veilE*al,0,.09)));
vg.addColorStop(1,rgba(vc,0));
dc.fillStyle=vg; dc.fillRect(0,0,W,Hh);
dc.globalCompositeOperation=oldOp;

// ---- 6. grain: silver halide ----
const gw=cl(Math.round(W/2),160,960), gh=cl(Math.round(gw*Hh/Math.max(1,W)),90,620);
const gkey=gw+'x'+gh+'|'+P.seed;
if(!S.gr||S.gk!==gkey){
  if(S.gr) for(let k=0;k<S.gr.length;k++) if(S.gr[k].remove) S.gr[k].remove();
  S.gr=[];
  for(let k=0;k<3;k++){
    const g=createGraphics(gw,gh); g.loadPixels();
    const q=g.pixels;
    for(let i=0;i<gw*gh;i++){
      const s=Math.sin((i*12.9898+k*78.233+P.seed*3.71))*43758.5453;
      const r1=s-Math.floor(s);
      const s2=Math.sin((i*39.3468+k*11.135+P.seed*7.13))*24634.6345;
      const r2=s2-Math.floor(s2);
      const v=128+(r1+r2-1)*72, o=i*4;
      q[o]=v; q[o+1]=v; q[o+2]=v; q[o+3]=255;
    }
    g.updatePixels(); S.gr.push(g);
  }
  S.gk=gkey; }
if(grainE>0.005){
  const idx=Math.abs(Math.floor(K.t*17))%3;
  const jt=Math.floor(K.t*17);
  const jx=((Math.sin(jt*45.11)*4371.9)%7+7)%7, jy=((Math.sin(jt*91.7)*7331.3)%7+7)%7;
  dc.imageSmoothingEnabled=false;
  // OVERLAY puts grain in the midtones, where the emulsion actually is...
  dc.globalCompositeOperation='overlay';
  dc.globalAlpha=cl(grainE*(bleach?.50:.38)*al,0,.58);
  image(S.gr[idx],-jx,-jy,W+14,Hh+14);
  // ...but overlay is a no-op on a near-black frame, so a whisper of additive
  // silver keeps the shadows from being dead flat plastic.
  dc.globalCompositeOperation='lighter';
  dc.globalAlpha=cl(grainE*.055*al,0,.09);
  image(S.gr[(idx+1)%3],-jy,-jx,W+14,Hh+14);
  dc.imageSmoothingEnabled=true;
  dc.globalAlpha=1; dc.globalCompositeOperation=oldOp;
}

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
